public void loadDeltaConditions()
{
    TFMLogicBlock                   block;
    MapEnumerator                   mEnum;
    TFMRegistrationCollectors       collectors;

    mEnum = blocks.getEnumerator();
    while (mEnum.moveNext())
    {
        block= mEnum.currentValue();
        //collectors = this.getBlockCollectors(block);
        collectors = blockCollectorMap.exists(block.getInstanceID()) ? blockCollectorMap.lookup(block.getInstanceID()) : null;
        if (collectors)
        {
            collectors.loadDeltaConditions(TFMProcess::getProcessDomain(), process.parmProcessName(), process.parmVersion());
        }
    }
}

