{
    return blockAddons.blockAddons(_block);
}

public void convertAddonsFromCodeToDelta(Version _newVersion)
{

    MapEnumerator                   blockEnum = blocks.getEnumerator();        
    MapEnumerator                   addonsEnum;
    TFMLogicBlock                   block;
    TFMLogicBlockAddonCollection    localAddons;
    process.parmVersion(_newVersion);
    localAddons= TFMLogicBlockAddonCollection::Construct(process);
    while (blockEnum.moveNext())
    {
        block = blockEnum.currentValue();
        addonsEnum = blockAddons.blockAddons(block).getEnumerator();
        while (addonsEnum.moveNext())
        {
            localAddons.addBlockAddon(block, addonsEnum.currentValue());
        }
    }

}

